#!/usr/bin/env python3
"""Read-only inode/usage and disk-space evidence for the existing warm Hermes."""
from __future__ import annotations

import base64
from contextlib import ExitStack
import hashlib
import json
import os
from pathlib import Path
import re
import signal
import stat
import time
import types

# Exact historical helper bytes are embedded for one-shot transport.
BUNDLE = {'owner_hermes_ram_preflight.py': '', 'owner_builder_proc_probe.py': ''}

PREFLIGHT = 'owner_hermes_ram_preflight.py'
PREFLIGHT_SHA = '6b1b0393101d485a12c2b0019095f2aa655c931385645ac655b88f916e154a10'
SECONDS = 14
SCHEMA = 'NOX_HERMES_COLD_PREFLIGHT_V1'
OLD_WEIGHTS = {
    'hermes': 'Hermes-3-Llama-3.1-8B.Q4_K_M.gguf',
    'dolphin': 'Dolphin3.0-Llama3.1-8B-Q4_K_M.gguf',
    'deep_hermes': 'NousResearch_DeepHermes-3-Llama-3-8B-Preview-Q4_K_M.gguf',
    'qwen25_coder': 'Qwen2.5-Coder-7B-Instruct-Q4_K_M.gguf',
    'saiga': 'saiga_nemo_12b.Q4_K_M.gguf',
    'vikhr': 'vikhr-nemo-12b-instruct-r-21-09-24-q4_k_m.gguf',
}
WEIGHT_ROOTS = {
    'tmpfs': Path('/dev/shm/nox_t802u/teachers'),
    'offload': Path('/root/nox/offload_shm_t888u/teachers'),
    'models': Path('/root/nox/models/teachers'),
}


def historical_probe():
    blob = base64.b64decode(BUNDLE.get(PREFLIGHT, ''), validate=True)
    if not blob or len(blob) > 65_536 or hashlib.sha256(blob).hexdigest() != PREFLIGHT_SHA:
        raise RuntimeError('HOLD_HERMES_COLD_PREFLIGHT_SOURCE')
    module = types.ModuleType('nox_hermes_observation_helpers')
    exec(compile(blob, '<pinned-preflight>', 'exec'), module.__dict__)
    module.BUNDLE = BUNDLE
    return module


def destination_snapshot(parent_fd, name):
    disk = os.fstatvfs(parent_fd)
    try:
        info = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        state = 'REGULAR' if stat.S_ISREG(info.st_mode) else 'PRESENT_NONREGULAR'
    except FileNotFoundError:
        state = 'ABSENT'
    return {'state': state, 'available_bytes': disk.f_bavail * disk.f_frsize}


def observe(probe, deadline, step=None):
    if step is None:
        step = [None]
    step[0] = 'load_proc_probe'
    helper = probe.proc_helper()
    step[0] = 'initial_guard'
    probe.tick(deadline)
    step[0] = 'open_ssd_parent'
    destination_fd = probe.open_plain(probe.SSD.parent)
    try:
        step[0] = 'ssd_statvfs'
        target = destination_snapshot(destination_fd, probe.SSD.name)
        report = {'destination': target, 'expected_bytes': probe.SIZE,
                  'warm_content_read_bytes': 0, 'hash_verified': False,
                  'host_mutations': False, 'migration_authorized': False}
        try:
            step[0] = 'open_warm_file'
            warm_fd = probe.open_plain(probe.WARM)
        except FileNotFoundError:
            return {**report, 'state': 'WARM_PATH_NOT_FOUND'}
        try:
            info = os.fstat(warm_fd)
            before = probe.identity(info)
            if not (stat.S_ISREG(info.st_mode) and info.st_size == probe.SIZE
                    and info.st_uid == os.geteuid() and info.st_nlink == 1
                    and info.st_dev == probe.SHM.stat().st_dev
                    and info.st_dev != os.fstat(destination_fd).st_dev):
                return {**report, 'state': 'HOLD_HERMES_WARM_IDENTITY'}
            def visible_pids():
                return sorted(int(item.name) for item in helper.PROC.iterdir() if item.name.isdigit())
            pids_before = visible_pids()
            step[0] = 'proc_usage'
            evidence = probe.process_refs(helper, before, warm_fd, deadline)
            probe.tick(deadline)
            same_pids = pids_before == visible_pids() and len(pids_before) == evidence['pids_seen']
            with ExitStack() as stack:
                step[0] = 'final_identity'
                warm_again = probe.open_plain(probe.WARM)
                stack.callback(os.close, warm_again)
                target_again = probe.open_plain(probe.SSD.parent)
                stack.callback(os.close, target_again)
                validated = (probe.identity(os.fstat(warm_again)) == before
                             and probe.identity(os.fstat(warm_fd)) == before
                             and os.path.samestat(os.fstat(target_again), os.fstat(destination_fd)))
                if not validated:
                    return {**report, 'state': 'HOLD_HERMES_INODE_CHANGED'}
                target = destination_snapshot(target_again, probe.SSD.name)
            return {**report, 'state': 'OBSERVED_EXACT_HERMES_WARM_METADATA',
                    'destination': target, 'warm_allocated_bytes': info.st_blocks * 512,
                    'destination_fits_payload_only': target['available_bytes'] >= probe.SIZE,
                    'visible_usage_complete': bool(same_pids and evidence['complete']),
                    'visible_pid_set_unchanged': same_pids,
                    'known_reference_count': evidence['known_reference_count'],
                    'visible_processes': evidence['pids_seen'],
                    'usage_observation_is_point_sample': True}
        finally:
            os.close(warm_fd)
    finally:
        os.close(destination_fd)


def leaf_metadata(path, known_target):
    try:
        info = path.lstat()
        if stat.S_ISLNK(info.st_mode):
            target = path.readlink()
            return {'state': 'SYMLINK', 'expected_target': target == known_target}
        if stat.S_ISREG(info.st_mode):
            return {'state': 'REGULAR', 'bytes': info.st_size, 'allocated_bytes': info.st_blocks * 512}
        return {'state': 'OTHER'}
    except FileNotFoundError:
        return {'state': 'ABSENT'}
    except OSError as error:
        return {'state': 'UNAVAILABLE', 'errno': error.errno}


def quick_metadata(probe):
    view = {
        'warm': leaf_metadata(probe.WARM, probe.SSD),
        'cold': leaf_metadata(probe.SSD, probe.WARM),
    }
    for name, path in (('cold_parent', probe.SSD.parent), ('nox_root', Path('/root/nox'))):
        try:
            disk = os.statvfs(path)
            view[name] = {'available_bytes': disk.f_bavail * disk.f_frsize}
        except OSError as error:
            view[name] = {'errno': error.errno}
    return view


def old_teacher_metadata(roots):
    rows = []
    for label, path in roots.items():
        try:
            resolved = path.resolve(strict=True)
        except FileNotFoundError:
            rows.append({'location': label, 'state': 'ABSENT'})
            continue
        except (OSError, RuntimeError):
            rows.append({'location': label, 'state': 'UNAVAILABLE'})
            continue
        if resolved not in roots.values():
            rows.append({'location': label, 'state': 'UNEXPECTED_PATH'})
            continue
        files = {}
        for model, filename in OLD_WEIGHTS.items():
            files[model] = leaf_metadata(resolved / filename, roots['tmpfs'] / filename)
        rows.append({'location': label, 'state': 'OBSERVED', 'files': files})
    return rows


def main():
    request, source = (os.environ.get(key, '') for key in
                       ('NOX_OWNER_REQUEST_ID', 'NOX_OWNER_SOURCE_SHA'))
    if not re.fullmatch(r'[0-9]{1,24}', request) or not re.fullmatch(r'[0-9a-f]{40}', source):
        raise RuntimeError('HOLD_HERMES_COLD_OWNER_CONTEXT')
    if signal.getitimer(signal.ITIMER_REAL) != (0.0, 0.0):
        raise RuntimeError('HOLD_HERMES_COLD_EXISTING_TIMER')
    def expired(*_):
        raise TimeoutError()
    previous = signal.signal(signal.SIGALRM, expired)
    signal.setitimer(signal.ITIMER_REAL, SECONDS)
    step = ['load_pinned_helpers']
    metadata = None
    teacher_metadata = None
    try:
        probe = historical_probe()
        step[0] = 'collect_quick_metadata'
        metadata = quick_metadata(probe)
        step[0] = 'collect_old_teacher_metadata'
        teacher_metadata = old_teacher_metadata(WEIGHT_ROOTS)
        result = observe(probe, time.monotonic() + SECONDS - 1, step)
    except (OSError, RuntimeError, ValueError, AttributeError, KeyError, TypeError) as error:
        result = {'state': 'HOLD_HERMES_COLD_OBSERVATION', 'host_mutations': False,
                  'migration_authorized': False, 'stage': step[0],
                  'error_class': type(error).__name__}
        if isinstance(error, OSError):
            result['errno'] = error.errno
        elif isinstance(error, RuntimeError) and re.fullmatch(r'HOLD_[A-Z_]{1,80}', str(error)):
            result['reason'] = str(error)
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, previous)
    result.update(schema=SCHEMA, request=request, source_sha=source,
                  metadata_only=metadata, old_teachers_metadata=teacher_metadata)
    print('NOX_MAINT_REPAIR=' + json.dumps({'kind': 'hermes_cold_preflight', 'data': result},
                                         separators=(',', ':')), flush=True)
    print('NOX_MAINT_REPAIR_COMPLETE=true', flush=True)


if __name__ == '__main__':
    main()
